{
  "format": "spec-v1",
  "product": { "name": "hn-digest", "version": "0.1.0", "kind": "agent" },
  "purpose": "hn-digest reads the current top stories on Hacker News and writes a short digest of the ones about a topic the caller names: for each story its title, its link, its points and one plain sentence on why it matters. It serves anyone who wants to know what Hacker News is saying about one subject today without reading the whole front page. It only reads; it never posts, votes or comments.",
  "users": [
    { "who": "A caller who follows a subject", "wants": "A short, trustworthy list of today's top Hacker News stories about that subject, each with why it matters, and nothing made up." }
  ],
  "source": { "kind": "account" },
  "features": [
    {
      "id": "F1",
      "name": "topic-digest",
      "does": "Reads the current top stories on Hacker News and writes a short digest of the ones about the caller's topic, each with title, link, points and one sentence on why it matters.",
      "inputs": [
        {
          "name": "topic",
          "kind": "text",
          "about": "The subject you want stories about, in a few words, such as \"rust compilers\" or \"climate policy\".",
          "required": true,
          "given_by": "person"
        }
      ],
      "outputs": [
        {
          "name": "digest",
          "kind": "text/markdown",
          "about": "The digest. A short header with the fields `Topic:`, `Read:` (how many top stories were read) and `Skipped:` (how many could not be read), then the heading `## Stories`. Under it, each story in Hacker News's top-story order as `### <title>`, then the lines `Link:` and `Points:`, then its one sentence on why it matters. When no story is about the topic, `## Stories` holds one line saying so instead of entries."
        }
      ],
      "requirements": [
        {
          "id": "F1.R1",
          "shall": "The agent shall read the current list of top stories from the public Hacker News API and then read each of the first stories on it, as many as the stories-to-read setting says.",
          "kind": "behavior",
          "priority": "must",
          "verify": "test",
          "source": { "said": "Reads the current top stories on Hacker News ... Settings: how many top stories to read (default 30, 10 to 100)" }
        },
        {
          "id": "F1.R2",
          "shall": "The agent shall put in the digest only the stories it read that are about the caller's topic, judged from each story's title and its own text on Hacker News, at most as many as the digest-size setting says, in the order they stand among the top stories.",
          "kind": "behavior",
          "priority": "must",
          "verify": "test",
          "rationale": "Judging from the title and the story's own text keeps the agent to the one system it reaches. Keeping Hacker News's own order is recommended; the person's words do not say an order.",
          "source": { "said": "writes a short digest of the ones about a topic the caller names ... how many to put in the digest (default 5, 1 to 10)" }
        },
        {
          "id": "F1.R3",
          "shall": "The agent shall give each story in the digest its title, its link and its points exactly as Hacker News gave them, and, for a story with no link of its own, the link to its discussion page on Hacker News.",
          "kind": "output",
          "priority": "must",
          "verify": "test",
          "rationale": "A story with no link of its own (an Ask HN post) is linked to its own page on Hacker News rather than left without a link or given one made up; recommended, since the person's words do not say.",
          "source": { "said": "each story's title, link, points" }
        },
        {
          "id": "F1.R4",
          "shall": "The agent shall give each story in the digest one plain sentence on why it matters, written by a model from only what the agent read from Hacker News about that story.",
          "kind": "output",
          "priority": "must",
          "verify": "test",
          "source": { "said": "one plain sentence on why it matters ... It uses a model to write the sentences" }
        },
        {
          "id": "F1.R5",
          "shall": "The agent shall refuse to write about any story it did not read from Hacker News in the same job, and shall leave out of the digest any story the model names that is not among the stories read.",
          "kind": "refusal",
          "priority": "must",
          "verify": "test",
          "source": { "said": "what it must refuse: Writing about stories it did not read from Hacker News" }
        },
        {
          "id": "F1.R6",
          "shall": "The agent shall refuse to invent points, links or comments: points and links shall be taken only from what Hacker News gave, never from the model, and the digest shall say nothing about any story's comments.",
          "kind": "refusal",
          "priority": "must",
          "verify": "test",
          "rationale": "The agent does not read comments, so it cannot report them truthfully; recommended reading of the person's words.",
          "source": { "said": "inventing points, links or comments" }
        },
        {
          "id": "F1.R7",
          "shall": "The agent shall refuse to post, vote or comment on Hacker News, shall send Hacker News nothing but reads, and shall answer a request to do so by saying it only reads.",
          "kind": "refusal",
          "priority": "must",
          "verify": "test",
          "source": { "said": "posting, voting or commenting on Hacker News ... (read only, no key)" }
        },
        {
          "id": "F1.R8",
          "shall": "When none of the stories it read is about the topic, the agent shall hand back a digest with no entries that says no story about the topic was found among the top stories read and how many it read, and shall not call this a failure or call the model to write sentences.",
          "kind": "behavior",
          "priority": "must",
          "verify": "test",
          "rationale": "The empty case. Recommended; the person's words do not say.",
          "source": { "said": "writes a short digest of the ones about a topic the caller names" }
        },
        {
          "id": "F1.R9",
          "shall": "When the topic is empty or only spaces, the agent shall read nothing and hand back no digest, and shall say that a topic is needed.",
          "kind": "input",
          "priority": "must",
          "verify": "test",
          "rationale": "Recommended; the person's words do not say what happens with no topic.",
          "source": { "said": "a topic the caller names" }
        },
        {
          "id": "F1.R10",
          "shall": "When fewer stories are about the topic than the digest-size setting allows, the agent shall put in only those, and shall never fill the digest with stories that are not about the topic.",
          "kind": "behavior",
          "priority": "must",
          "verify": "test",
          "source": { "said": "a short digest of the ones about a topic the caller names" }
        },
        {
          "id": "F1.R11",
          "shall": "The agent shall read 30 top stories and put at most 5 in the digest when no setting is given, and shall refuse a stories-to-read setting outside 10 to 100 or a digest-size setting outside 1 to 10 by saying the allowed range, reading nothing.",
          "kind": "default",
          "exact": ["30", "5", "10", "100", "1"],
          "priority": "must",
          "verify": "test",
          "rationale": "Refusing an out-of-range value, rather than quietly moving it into range, is recommended; the person's words give the ranges but not what happens outside them.",
          "source": { "said": "how many top stories to read (default 30, 10 to 100) and how many to put in the digest (default 5, 1 to 10)" }
        },
        {
          "id": "F1.R12",
          "shall": "When the Hacker News API cannot be reached, answers with an error, or gives a top-stories list it cannot read, the agent shall stop, hand back no digest, and say that Hacker News could not be read, and shall never write a digest from anywhere else.",
          "kind": "error",
          "priority": "must",
          "verify": "test",
          "rationale": "The failure case for the one system it reaches. Recommended; the person's words do not say.",
          "source": { "said": "It reaches one system, the public Hacker News API" }
        },
        {
          "id": "F1.R13",
          "shall": "When a single top story cannot be read, the agent shall leave it out, go on with the others, and give in the digest's header how many stories it skipped.",
          "kind": "error",
          "priority": "should",
          "verify": "test",
          "rationale": "One bad story should not lose the whole digest, and the skip is said rather than hidden. Recommended; the person's words do not say.",
          "source": { "said": "Reads the current top stories on Hacker News" }
        },
        {
          "id": "F1.R14",
          "shall": "When the model fails, answers in a way the agent cannot read, or its call is refused because the spending ceiling is reached, the agent shall stop, hand back no digest, and say that the sentences could not be written, and shall never write a sentence of its own in the model's place.",
          "kind": "error",
          "priority": "must",
          "verify": "test",
          "rationale": "A digest whose sentences are made up by the code would break the refusal to invent. Failing whole is recommended over handing back a digest without sentences; the person's words do not say.",
          "source": { "said": "It uses a model to write the sentences, with a spending ceiling of 1 USD per day." }
        }
      ],
      "acceptance": [
        {
          "id": "F1.A1",
          "gherkin": "Scenario: A digest of the stories about the topic\n  Given Hacker News lists 12 top stories, and 3 of the first 10 are about \"rust\"\n  And the stories-to-read setting is 10 and the digest-size setting is 5\n  When the caller asks for a digest about \"rust\"\n  Then the agent reads the top-stories list and the first 10 stories, and no others\n  And the digest holds those 3 stories, in the order they stand among the top stories\n  And no story that is not about \"rust\" is in it\n  And each has the title, link and points Hacker News gave, and one sentence from the model",
          "checks": ["F1.R1", "F1.R2", "F1.R3", "F1.R4", "F1.R10"]
        },
        {
          "id": "F1.A2",
          "gherkin": "Scenario: The digest stops at its size\n  Given 8 of the stories read are about the topic\n  And the digest-size setting is 5\n  When the caller asks for a digest about the topic\n  Then the digest holds 5 stories, the first 5 of the 8 in top-story order",
          "checks": ["F1.R2"]
        },
        {
          "id": "F1.A3",
          "gherkin": "Scenario: A story with no link of its own\n  Given a story about the topic is an Ask HN post with no link of its own\n  When the caller asks for a digest about the topic\n  Then that story's link is its discussion page on Hacker News",
          "checks": ["F1.R3"]
        },
        {
          "id": "F1.A4",
          "gherkin": "Scenario: The model names a story that was not read, and gives its own points and link\n  Given the model's answer names a story id that is not among the stories read\n  And it gives other points and another link for a story that was read\n  When the agent writes the digest\n  Then the story that was not read is not in the digest\n  And the story that was read carries the points and link Hacker News gave, not the model's\n  And the digest says nothing about any story's comments",
          "checks": ["F1.R5", "F1.R6"]
        },
        {
          "id": "F1.A5",
          "gherkin": "Scenario: Asked to post, vote or comment\n  Given a caller asks the agent to upvote a story or post a comment\n  When the agent runs\n  Then it says it only reads Hacker News\n  And every request it sent to Hacker News, in this and every other scenario, is a read",
          "checks": ["F1.R7"]
        },
        {
          "id": "F1.A6",
          "gherkin": "Scenario: No story is about the topic\n  Given none of the 30 stories read is about \"underwater basket weaving\"\n  When the caller asks for a digest about \"underwater basket weaving\"\n  Then the digest has no entries\n  And it says no story about the topic was found among the 30 top stories read\n  And the job does not fail\n  And the model is not asked to write sentences",
          "checks": ["F1.R8"]
        },
        {
          "id": "F1.A7",
          "gherkin": "Scenario: No topic given\n  Given the topic is only spaces\n  When the caller asks for a digest\n  Then the agent reads nothing from Hacker News\n  And it hands back no digest and says a topic is needed",
          "checks": ["F1.R9"]
        },
        {
          "id": "F1.A8",
          "gherkin": "Scenario: The settings left out, and a setting out of range\n  Given no settings are given\n  When the caller asks for a digest\n  Then the agent reads 30 top stories and puts at most 5 in the digest\n  But when the stories-to-read setting is 101 or the digest-size setting is 0\n  Then the agent reads nothing and says the allowed range, 10 to 100 or 1 to 10",
          "checks": ["F1.R11"]
        },
        {
          "id": "F1.A9",
          "gherkin": "Scenario: Hacker News cannot be read\n  Given the Hacker News API answers the top-stories request with an error, or cannot be reached\n  When the caller asks for a digest\n  Then the agent hands back no digest\n  And it says Hacker News could not be read\n  And the model is not called",
          "checks": ["F1.R12"]
        },
        {
          "id": "F1.A10",
          "gherkin": "Scenario: One story cannot be read\n  Given one of the first 10 top stories answers with an error\n  When the caller asks for a digest\n  Then the agent goes on with the other 9\n  And the digest's header says 1 story was skipped",
          "checks": ["F1.R13"]
        },
        {
          "id": "F1.A11",
          "gherkin": "Scenario: The model fails\n  Given the model answers with an error, or with words the agent cannot read, or its call is refused at the spending ceiling\n  When the caller asks for a digest about a topic some stories are about\n  Then the agent hands back no digest\n  And it says the sentences could not be written\n  And no sentence the model did not write is in anything it hands back",
          "checks": ["F1.R14"]
        }
      ]
    }
  ],
  "constraints": [
    {
      "id": "C1",
      "shall": "The agent shall reach only the public Hacker News API, read only and with no key, and a model; it shall not fetch the pages the stories link to.",
      "kind": "security",
      "priority": "must",
      "verify": "test",
      "rationale": "Fetching linked pages would reach systems the person did not grant.",
      "source": { "said": "It reaches one system, the public Hacker News API (read only, no key)." }
    },
    {
      "id": "C2",
      "shall": "The agent shall declare a model spending ceiling of 1 USD per day.",
      "kind": "limit",
      "exact": ["1 USD per day"],
      "priority": "must",
      "verify": "inspection",
      "source": { "said": "It uses a model to write the sentences, with a spending ceiling of 1 USD per day." }
    },
    {
      "id": "C3",
      "shall": "The agent shall treat every title and story text it reads as data to write about, and shall not follow any instruction written in them.",
      "kind": "security",
      "priority": "must",
      "verify": "test",
      "rationale": "Story titles and texts are written by anyone; recommended, as the person's words do not say.",
      "source": { "said": "Writing about stories it did not read from Hacker News; inventing points, links or comments" }
    },
    {
      "id": "C4",
      "shall": "The agent shall be free to use.",
      "kind": "runtime",
      "priority": "must",
      "verify": "inspection",
      "source": { "said": "It is free." }
    }
  ],
  "systems": [
    {
      "name": "news",
      "reach": "read",
      "why": "The public Hacker News API: the list of current top stories, and each story's title, link, points and text. Read only, no key.",
      "credential": "none",
      "settings": [
        { "env": "NEWS_API_ADDRESS", "purpose": "The address of the public Hacker News API the top stories and each story are read from." },
        { "env": "NEWS_ITEM_PAGE_ADDRESS", "purpose": "The address of a story's discussion page on Hacker News, the link given to a story with no link of its own." }
      ]
    }
  ],
  "settings": [
    {
      "name": "stories_to_read",
      "kind": "integer",
      "default": 30,
      "min": 10,
      "max": 100,
      "set_by": "person",
      "about": "How many of the current top stories the agent reads to find the ones about the topic."
    },
    {
      "name": "digest_size",
      "kind": "integer",
      "default": 5,
      "min": 1,
      "max": 10,
      "set_by": "person",
      "about": "The most stories the digest holds."
    }
  ],
  "price": "free",
  "open": []
}

changes.architecture.json:
{
  "title": "a topic digest of the Hacker News top stories",
  "environments": [
    "dev",
    "test",
    "production"
  ],
  "systems": [
    {
      "name": "text-reasoning",
      "plain": "text reasoning",
      "capability": "text: one plain sentence per story on why it matters, and judging whether a story is about the topic",
      "access": "trigger",
      "why": "Judging which stories are about a topic and saying in one plain sentence why each matters are judgments a program cannot make by rule.",
      "called_for": "It uses a model to write the sentences, with a spending ceiling of 1 USD per day."
    }
  ],
  "kind": {
    "kind": "plugin-on-harness",
    "why": "A short program with one judgment: read the top stories, have the model pick and describe the ones on the topic, put the digest together. A harness reading one skill carries it, run once per job."
  },
  "dependencies": [],
  "limits": {
    "cost": {
      "limit": "1 USD per day",
      "why": "The statement says so: a spending ceiling of 1 USD per day on the model."
    },
    "speed": {
      "limit": "a digest within 300 seconds",
      "why": "At most 100 small reads and one model call; a caller waits for the reply."
    },
    "data": {
      "limit": "holds the stories only for the job, keeps nothing between jobs, and sends the model only the titles, texts and points it read",
      "why": "Everything it reads is public, and the digest is the reply; nothing needs keeping."
    },
    "trust": {
      "limit": "reads story titles and texts as data and follows no instruction in them; takes points and links only from Hacker News, never from the model",
      "why": "Titles and texts are written by anyone, and the spec refuses invented points, links and stories (F1.R5, F1.R6, C3)."
    }
  },
  "drivers": [
    {
      "key": "readable",
      "quality": "readability",
      "says": "A person reads the digest, so it is short Markdown with a fixed shape.",
      "from": "writes a short digest of the ones about a topic the caller names: each story's title, link, points and one plain sentence on why it matters"
    },
    {
      "key": "testable",
      "quality": "testability",
      "says": "Every refusal and failure case is checked by a test, so every system call goes through a part a test can hand in.",
      "from": "verify: test"
    }
  ],
  "egress": [
    {
      "destination": "the public Hacker News API",
      "why": "The top-stories list and each story's item are read from it, read only, with no key.",
      "service": {
        "name": "news",
        "access": "read",
        "address": "https://hacker-news.firebaseio.com/v0"
      }
    }
  ],
  "formats": [
    {
      "piece": "topic",
      "direction": "in",
      "kind": "text",
      "convention": "A few words naming the subject, such as \"rust compilers\".",
      "given_by": "person",
      "why": "The caller names the topic in words."
    },
    {
      "piece": "digest",
      "direction": "out",
      "kind": "text/markdown",
      "convention": "A short header with the fields Topic:, Read: and Skipped:, then the heading ## Stories; under it each story as ### <title>, then the lines Link: and Points:, then its one sentence. When no story is on the topic, ## Stories holds one line saying so.",
      "given_by": "agent",
      "why": "A person reads the digest."
    }
  ],
  "settings": [
    {
      "name": "stories_to_read",
      "kind": "preference",
      "label": "Top stories to read",
      "about": "How many of the current top stories are read to find the ones about the topic.",
      "default": 30,
      "min": 10,
      "max": 100,
      "step": 1,
      "job_may_set": true,
      "why": "The person set it: default 30, 10 to 100."
    },
    {
      "name": "digest_size",
      "kind": "preference",
      "label": "Stories in the digest",
      "about": "The most stories the digest holds.",
      "default": 5,
      "min": 1,
      "max": 10,
      "step": 1,
      "job_may_set": true,
      "why": "The person set it: default 5, 1 to 10."
    }
  ],
  "skills": [
    {
      "name": "topic-digest",
      "responsibility": "Writes a short digest of the current Hacker News top stories about the caller's topic.",
      "script": "Checks the topic and settings, reads the top stories, has the model pick the ones on the topic and write one sentence each, and writes the digest or says why there is none."
    }
  ],
  "parts": [
    {
      "id": "news-client",
      "name": "Hacker News client",
      "within": "topic-digest",
      "responsibility": "Reads the top-story ids, then each of the first stories' items a bounded number at a time, and counts the ones it could not read.",
      "reaches": "news"
    },
    {
      "id": "sentence-writer",
      "name": "sentence writer",
      "within": "topic-digest",
      "responsibility": "Asks the model, through the shared model caller, which stories read are about the topic and for one plain sentence on each, and keeps only answers that name stories that were read.",
      "reaches": "text-reasoning"
    },
    {
      "id": "digest-writer",
      "name": "digest writer",
      "within": "topic-digest",
      "responsibility": "Puts the Markdown digest together in top-story order, with titles, links and points taken from what was read, up to the digest size, or the empty digest."
    }
  ],
  "flow": [
    {
      "from": "caller",
      "to": "harness",
      "data": "the topic and the settings",
      "says": "The caller names a topic, and may set how many stories to read and to keep."
    },
    {
      "from": "harness",
      "to": "news-client",
      "data": "the topic, stories_to_read and digest_size",
      "says": "The harness starts the script once with the job, which checks the topic and the settings before reading anything."
    },
    {
      "from": "news",
      "to": "news-client",
      "data": "the top-story ids, then each story's title, link, points and text",
      "says": "The client reads the list, then the first stories on it."
    },
    {
      "from": "news-client",
      "to": "sentence-writer",
      "data": "the stories read",
      "says": "The stories read go to the writer, with their ids."
    },
    {
      "from": "sentence-writer",
      "to": "text-reasoning",
      "data": "the topic and each story's id, title and text",
      "says": "One model call picks the stories on the topic and writes one sentence for each."
    },
    {
      "from": "sentence-writer",
      "to": "digest-writer",
      "data": "the ids picked and a sentence for each",
      "says": "Only ids among the stories read are kept."
    },
    {
      "from": "digest-writer",
      "to": "caller",
      "data": "the digest",
      "says": "The digest goes back as the reply, through the harness."
    }
  ],
  "decisions": [
    {
      "decided": "Code controls the job, and the model is called once, to pick the stories on the topic and write their sentences",
      "context": "Every job is the same: read the top stories, keep the ones on a topic, describe each, write the digest. Only picking and describing are judgments.",
      "drivers": [
        "cost",
        "speed",
        "trust"
      ],
      "why": "One model call per job bounds the spend far under the ceiling and the time, and code that owns the points and links cannot let the model invent them.",
      "alternatives": [
        {
          "option": "A model in control, reading Hacker News through tools and writing the digest",
          "why_not": "What it reads, spends and writes would not be bounded, and points or links could come from the model."
        },
        {
          "option": "One model call per story",
          "why_not": "Up to 100 calls a job against a ceiling of 1 USD per day, for no better sentences."
        },
        {
          "option": "Matching the topic by keywords in code",
          "why_not": "A topic is a subject, not a word; \"rust\" in a title is not always the language."
        }
      ],
      "consequences": [
        "The job's how is control script, intelligence called, contract full.",
        "Only the sentence writer reaches the model, and the digest writer takes titles, links and points only from what the client read."
      ]
    },
    {
      "decided": "A package on a harness, run once per job",
      "context": "A digest is asked for now and then, and nothing needs to stay between jobs.",
      "drivers": [
        "cost",
        "data"
      ],
      "why": "Nothing runs, and nothing is spent, between jobs.",
      "alternatives": [
        {
          "option": "A long-running service that keeps a cache of the top stories",
          "why_not": "A cache would serve stories that are no longer current and needs a store the statement does not call for."
        }
      ],
      "consequences": [
        "The script reads its settings and the model's four settings on every run."
      ]
    },
    {
      "decided": "Read the story items in parallel, a bounded number at a time, and leave out one that cannot be read",
      "context": "Up to 100 items are read one request each.",
      "drivers": [
        "speed",
        "trust"
      ],
      "why": "In parallel the job stays well inside its time; bounded, it does not flood a public service.",
      "alternatives": [
        {
          "option": "One at a time",
          "why_not": "Up to 100 requests in a row is slow."
        },
        {
          "option": "All at once",
          "why_not": "Up to 100 open requests to a public service at once."
        }
      ],
      "consequences": [
        "The bound is a constant a test can see.",
        "A story that cannot be read is counted in Skipped: in the header."
      ]
    },
    {
      "decided": "Answer with the digest in the reply, and store nothing",
      "context": "The caller wants the digest now.",
      "drivers": [
        "data",
        "speed",
        "readable"
      ],
      "why": "The reply is the digest; storing it would need a system nobody granted.",
      "alternatives": [
        {
          "option": "Store each digest and reply with a link",
