{
  "format": "spec-v1",
  "product": {
    "name": "hn-digest",
    "version": "0.1.0",
    "kind": "agent"
  },
  "purpose": "hn-digest reads the current top stories on Hacker News and writes a short digest of the ones about a topic the caller names: for each story its title, its link, its points and one plain sentence on why it matters. It serves anyone who wants to know what Hacker News is saying about one subject today without reading the whole front page. It only reads; it never posts, votes or comments.",
  "users": [
    {
      "who": "A caller who follows a subject",
      "wants": "A short, trustworthy list of today's top Hacker News stories about that subject, each with why it matters, and nothing made up."
    }
  ],
  "source": {
    "kind": "account"
  },
  "features": [
    {
      "id": "F1",
      "name": "topic-digest",
      "does": "Reads the current top stories on Hacker News and writes a short digest of the ones about the caller's topic, each with title, link, points and one sentence on why it matters.",
      "inputs": [
        {
          "name": "topic",
          "kind": "text",
          "about": "The subject you want stories about, in a few words, such as \"rust compilers\" or \"climate policy\".",
          "required": true,
          "given_by": "person"
        }
      ],
      "outputs": [
        {
          "name": "digest",
          "kind": "text/markdown",
          "about": "The digest. A short header with the fields `Topic:`, `Read:` (how many top stories were read) and `Skipped:` (how many could not be read), then the heading `## Stories`. Under it, each story in Hacker News's top-story order as `### <title>`, then the lines `Link:` (or `Link: none (a Hacker News post with no link of its own)` for a story with no link of its own) and `Points:`, then its one sentence on why it matters. When no story is about the topic, `## Stories` holds one line saying so instead of entries."
        }
      ],
      "requirements": [
        {
          "id": "F1.R1",
          "shall": "The agent shall read the current list of top stories from the public Hacker News API and then read each of the first stories on it, as many as the stories-to-read setting says.",
          "kind": "behavior",
          "priority": "must",
          "verify": "test",
          "source": {
            "said": "Reads the current top stories on Hacker News ... Settings: how many top stories to read (default 30, 10 to 100)"
          }
        },
        {
          "id": "F1.R2",
          "shall": "The agent shall put in the digest only the stories it read that are about the caller's topic, judged from each story's title and its own text on Hacker News, at most as many as the digest-size setting says, in the order they stand among the top stories.",
          "kind": "behavior",
          "priority": "must",
          "verify": "test",
          "rationale": "Judging from the title and the story's own text keeps the agent to the one system it reaches. Keeping Hacker News's own order is recommended; the person's words do not say an order.",
          "source": {
            "said": "writes a short digest of the ones about a topic the caller names ... how many to put in the digest (default 5, 1 to 10)"
          }
        },
        {
          "id": "F1.R3",
          "shall": "The agent shall give each story in the digest its title, its link and its points exactly as Hacker News gave them, and, for a story with no link of its own, shall keep it in the digest with the line Link: none (a Hacker News post with no link of its own).",
          "kind": "output",
          "priority": "must",
          "verify": "test",
          "rationale": "A story with no link of its own (an Ask HN post) stays in the digest and says it has no link, rather than being given one made up; the person chose this in their changes.",
          "source": {
            "said": "each story's title, link, points ... A story with no link of its own stays in the digest with the line: Link: none (a Hacker News post with no link of its own)."
          },
          "exact": [
            "Link: none (a Hacker News post with no link of its own)"
          ]
        },
        {
          "id": "F1.R4",
          "shall": "The agent shall give each story in the digest one plain sentence on why it matters, written by a model from only what the agent read from Hacker News about that story.",
          "kind": "output",
          "priority": "must",
          "verify": "test",
          "source": {
            "said": "one plain sentence on why it matters ... It uses a model to write the sentences"
          }
        },
        {
          "id": "F1.R5",
          "shall": "The agent shall refuse to write about any story it did not read from Hacker News in the same job, and shall leave out of the digest any story the model names that is not among the stories read.",
          "kind": "refusal",
          "priority": "must",
          "verify": "test",
          "source": {
            "said": "what it must refuse: Writing about stories it did not read from Hacker News"
          }
        },
        {
          "id": "F1.R6",
          "shall": "The agent shall refuse to invent points, links or comments: points and links shall be taken only from what Hacker News gave, never from the model, and the digest shall say nothing about any story's comments.",
          "kind": "refusal",
          "priority": "must",
          "verify": "test",
          "rationale": "The agent does not read comments, so it cannot report them truthfully; recommended reading of the person's words.",
          "source": {
            "said": "inventing points, links or comments"
